// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.assume(amount > 0);

        Recorder rec = new Recorder();

        vm.prank(actor);
        c.SetLogFile(address(rec));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && rec.count() == 1);
    }
}

contract Recorder {
    uint256 public count;
    function AddMessage(address, uint256, string memory) external payable { count++; }
    receive() external payable {}
}
